#!/usr/bin/env texlua
-- Keeps the generated "Dependencies" section of every release unit's
-- README.md in step with the dependency matrix of tools/packages.lua.  The
-- section sits between the markers
--
--   <!-- BEGIN DEPENDENCIES (generated by tools/make-package-readmes.lua) -->
--   <!-- END DEPENDENCIES -->
--
-- A README without the markers gets the section appended.  It is rewritten
-- by "l3build tag" and checked before "l3build ctan".
--
-- Usage (from the bundle root):
--   texlua tools/make-package-readmes.lua [--check] [<unit>]

local metadata = dofile("tools/ctan-metadata.lua")
local packages = dofile("tools/packages.lua")

local BEGIN = "<!%-%- BEGIN DEPENDENCIES.-%-%->"
local END   = "<!%-%- END DEPENDENCIES %-%->"

local function fail(message)
  io.stderr:write("make-package-readmes: " .. message .. "\n")
  os.exit(1)
end

local check, name = false, nil
for _, argument in ipairs(arg) do
  if argument == "--check" then
    check = true
  elseif argument:match("^%-") then
    fail("unknown argument " .. argument)
  else
    name = argument
  end
end

local units = metadata.units()
if name then
  units = { metadata.unit(name) or fail("no such release unit: " .. name) }
end

local stale = 0
for _, unit in ipairs(units) do
  local path = metadata.readme_path(unit)
  local content = packages.read_file(path) or fail("cannot read " .. path)
  local section = metadata.dependency_section(unit)
  local from, to = content:find(BEGIN)
  local result
  if from then
    local _, last = content:find(END, to)
    if not last then
      fail(path .. ": BEGIN DEPENDENCIES without END DEPENDENCIES")
    end
    result = content:sub(1, from - 1) .. section .. content:sub(last + 1)
  else
    result = content:gsub("\n*$", "") .. "\n\n" .. section .. "\n"
  end
  if result ~= content then
    if check then
      print(path .. " is out of date")
      stale = stale + 1
    else
      local handle = io.open(path, "wb") or fail("cannot write " .. path)
      handle:write(result)
      handle:close()
      print("Wrote " .. path)
    end
  end
end

if check then
  if stale > 0 then
    io.stderr:write("make-package-readmes: run 'texlua tools/make-package-readmes.lua' (or 'l3build tag')\n")
    os.exit(1)
  end
  print("Package READMEs are up to date")
end
